function run_heap(values)
{

    var checksum = 0
    for (let repetition in 0 to 16) {
        let queue = copy(values)
 heap::heapify(queue)
        for (let position in 0 to len(values)) {
            let value = heap::pop(queue)
            checksum = checksum + value * (position + 1)
        }
    }
    return checksum + 0
}
let values = []
for (let i in 0 to 512) { values.append((i * 73 + 19) % 1009 - 500) }
let started = clock_ns()
let result = run_heap(values)
let elapsed = clock_ns() - started
print(result)
print(elapsed)

